function validateContractorFile(o){if(!o||o.application!==APP||o.fileType!=='contractor'||![1,2].includes(o.schemaVersion)||!o.contractor)throw Error('Файл не является файлом подрядчика модели.');const c=o.contractor;if(typeof c.id!=='string'||typeof c.name!=='string'||!Array.isArray(c.contracts))throw Error('Некорректные данные подрядчика.');const ids=new Set(),numbers=new Set();for(const d of c.contracts){if(typeof d.id!=='string'||!d.id||ids.has(d.id)||typeof d.number!=='string'||!d.number||numbers.has(d.number))throw Error('Повторяющийся или пустой договор в файле подрядчика.');ids.add(d.id);numbers.add(d.number);if(!Array.isArray(d.versions))throw Error('У договора отсутствуют версии.');for(const v of d.versions){const currency=v.currency||d.currency||'RUB',rawRate=v.fxRate??d.fx,rate=currency==='RUB'?1:(rawRate==null||rawRate===''?0:Number(rawRate));if(!CURRENCIES[currency])throw Error('Неподдерживаемая валюта: '+currency);if(!Number.isFinite(rate)||rate<0)throw Error('Контрактный курс не может быть отрицательным.');}}return clone(c);}
