function applyWorkbookEdits(c,book){
 const rates=book.sheets.find(x=>x.name==='Параметры');
 if(rates?.rows[0]?.[2]==='Валюта')for(const row of rates.rows.slice(1)){
  const d=c.contracts.find(x=>x.number===String(row?.[0])),v=d?.versions.find(x=>x.name===row?.[1]);
  const entry=COST_DEFS.find(x=>x[1]===row?.[4]&&(x[0]==='direct'?'Прямые':'Косвенные')===row?.[5]);
  if(!entry||!v)continue;const p=v.parameters[entry[2]];
  if(row[6]!==''&&row[6]!=null){if(!Number.isFinite(Number(row[6])))throw Error('В Excel некорректная ставка: '+row[4]);p.value=Number(row[6]);}
  if(['fixed','driver','manual',entry[3]].includes(row[7]))p.method=row[7];
  if(typeof row[8]==='string')p.rateBasis=row[8];
  if(typeof row[9]==='string')p.rateSource=row[9];
  if(Number.isInteger(Number(row[10]))&&Number(row[10])>=0)p.lag=Number(row[10]);
  if(typeof row[11]==='boolean')p.enabled=row[11];if(typeof row[12]==='boolean')p.cash=row[12];if(typeof row[13]==='boolean')p.vat=row[13];
  if(CURRENCIES[row[14]])p.rateCurrency=row[14];
 }
 const model=book.sheets.find(x=>x.name==='Модель');
 if(model?.rows[0]?.[0]==='Договор')for(const row of model.rows.slice(1)){
  const d=c.contracts.find(x=>x.number===String(row?.[0])),v=d?.versions.find(x=>x.name===row?.[1]&&x.year===Number(row?.[2]));
  const definition=SERIES.find(([key,label])=>row?.[5]==='Источник: '+label);
  if(!v||!definition)continue;
  const values=row.slice(6,18);if(values.length!==12||values.some(x=>!Number.isFinite(Number(x))))throw Error('В Excel некорректный месячный ряд: '+row[5]);
  v.drivers[definition[0]]=values.map(Number);
 }
 return c;
}
async function contractorFromUrl(meta){if(!meta.fileUrl)return {...meta,contracts:[]};const u=safeURL(meta.fileUrl),r=await fetch(u,{cache:'no-store',credentials:u.origin===location.origin?'same-origin':'omit'});if(!r.ok)throw Error(meta.name+': HTTP '+r.status);const book=await readWorkbook(await r.arrayBuffer(),meta.fileUrl.split('/').pop()||'contractor.xlsx'),sheet=book.sheets.find(x=>x.name==='_DATA');if(!sheet)throw Error(meta.name+': в Excel отсутствует служебный лист _DATA.');const raw=sheet.rows.slice(1).map(x=>String(x?.[0]??'')).join('');const c=validateContractorFile(JSON.parse(raw));if(c.id!==meta.id)throw Error(meta.name+': идентификатор в файле не совпадает с общим конфигом.');c.fileUrl=meta.fileUrl;return applyWorkbookEdits(c,book);}
