function persist(change=false,scope='contractor'){if(change){dirty=true;if(scope==='config'||scope==='both')configDirty=true;if(scope==='contractor'||scope==='both'){pendingContractors.add(state.currentContractor);contractorDirty=true;}state.revision=uid('config');}const files=[contractorDirty?'файл подрядчика':'',configDirty?'config.json':''].filter(Boolean);$('footerStatus').textContent=dirty?'Есть несохранённые изменения • скачайте '+files.join(' и '):'Данные загружены из внешних файлов';if($('saveStatus'))$('saveStatus').textContent=dirty?'Есть изменения для выгрузки: '+files.join(' и '):'Постоянное браузерное хранилище не используется';}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
