 const v=version(),equivalent=n=>v.currency==='RUB'?'':state.displayCurrency==='rub'?`<small class="sub">Исходно: ${fmtRaw(n)} ${v.currency}</small>`:`<small class="sub">Эквивалент: ${fmtRub(n,v)} RUB</small>`;
