 $('summaryTable').innerHTML=longitudinalTable('summary');$('summaryYears').innerHTML='';const toggleSummary=el=>{const key=el.dataset.summaryToggle,open=!el.classList.contains('expanded');el.classList.toggle('expanded',open);$('summaryTable').querySelectorAll('.detail-'+key).forEach(x=>x.classList.toggle('hidden',!open));if(key==='costs'&&!open)$('summaryTable').querySelectorAll('[data-summary-toggle="direct"],[data-summary-toggle="indirect"]').forEach(group=>{group.classList.remove('expanded');$('summaryTable').querySelectorAll('.detail-'+group.dataset.summaryToggle).forEach(x=>x.classList.add('hidden'));});};$('summaryTable').querySelectorAll('[data-summary-toggle]').forEach(el=>{el.onclick=()=>toggleSummary(el);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();toggleSummary(el);}};});
 const meta=v.workSourceMeta||{},loaded=!!meta.loadedAt&&meta.boqRows>0&&meta.ksgRows>0;
