 const kindField=x=>editMode?`<label class="kq-kind">Вид материала <input data-kq-material-kind="${esc(x.code)}" aria-label="Вид материала для ${esc(x.code)}" maxlength="80" value="${esc(kinds[x.code]||'')}" placeholder="Назначить"></label>`:kinds[x.code]?`<small class="kq-kind">Материал: ${esc(kinds[x.code])}</small>`:'';
 table.innerHTML=`<table class="small-table kq-table"><thead><tr><th>KQ-2</th><th>Наименование / вид материала</th><th>Объём BOQ</th><th>Объём КСГ</th><th>Отклонение</th><th>Трудозатраты,<br>чел.-ч</th><th>Техника,<br>маш.-ч</th><th>СМР / материалы BOQ,<br>${unitName(money)}</th><th>Цена СМР,<br>${money}/ед.</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${esc(x.code)}</td><td>${esc(x.name)}${kindField(x)}</td><td>${fmtWhole(x.quantity)}</td><td>${fmtWhole(x.scheduledQuantity)}</td><td class="${x.quantityVariance<0?'negative':''}">${fmtWhole(x.quantityVariance)}</td><td>${fmtWhole(x.laborHours)}</td><td>${fmtWhole(x.machineHours)}</td><td>${fmt(x.cost,v)}<small class="kq-material">МТР: ${x.materialsCost==null?'—':missingFx&&state.displayCurrency==='rub'?'курс не задан':x.materialsCost===0?'0,0':Math.abs(displayAmount(x.materialsCost,v))<state.unit*.05?(x.materialsCost<0?'>−0,1':'<0,1'):fmt(x.materialsCost,v)}${x.materialsRows!=null&&x.materialsRows<x.sourceRows?' · данных '+x.materialsRows+'/'+x.sourceRows:''}</small></td><td>${fmtKq(displayAmount(x.rate,v))}</td></tr>`).join('')}</tbody></table>`;
