function makeDetailedModelTable(r){const v=version(),allWorks=rankedWorks(v),works=topWorkRows(v),otherAmounts=Array.from({length:12},(_,m)=>r.revenue[m]-(v.drivers.otherRevenue[m]||0)-sum(allWorks.slice(0,10).map(x=>x.amounts[m])));let tech=`<tr class="table-section"><td colspan="14">Технико-экономические показатели</td></tr>`;tech+=treeRow({key:'model-top-works',label:'КФО',row:Array(12).fill(0),toggle:true,raw:true});tech+=works.map(x=>treeRow({parent:'model-top-works',label:x.label,row:x.volumes,level:1,raw:true})).join('');tech+=treeRow({label:'Основной персонал, FTE',row:v.drivers.directPeople,raw:true});tech+=treeRow({label:'Вспомогательный персонал, FTE',row:v.drivers.auxiliaryPeople,raw:true});tech+=treeRow({label:'Косвенный персонал, FTE',row:v.drivers.indirectPeople,raw:true});tech+=treeRow({label:'Техника, FTE',row:fteRow(v.drivers.equipmentHours),raw:true});const economy=`<tr class="table-section"><td colspan="14">Экономические показатели</td></tr>`;let html=makeModelTable(r).replace(/<tr class="table-section"><td colspan="14">Технико-экономические показатели<\/td><\/tr>[\s\S]*?<tr class="table-section"><td colspan="14">Экономические показатели<\/td><\/tr>/,tech+economy);if(allWorks.length){const details=allWorks.slice(0,10).map(x=>treeRow({parent:'model-income',label:x.label,row:x.amounts,level:1})).join('')+treeRow({parent:'model-income',label:'Прочие работы / остаток',row:otherAmounts,level:1})+treeRow({parent:'model-income',label:'Прочие доходы',row:v.drivers.otherRevenue,level:1});html=html.replace(/(<tr[^>]*data-tree-key="model-income"[\s\S]*?<\/tr>)[\s\S]*?(<tr[^>]*data-tree-key="model-costs")/,'$1'+details+'$2');}return html;}
