 for(const [kind,object] of [['cost',v.manualCosts],['payment',v.manualPayments]])for(const [k,row] of Object.entries(object)){const def=COST_DEFS.find(x=>x[2]===k);$('driverParameters').querySelector('tbody').insertAdjacentHTML('beforeend',`<tr><td>${kind==='cost'?'Начисление':'Выплата'}: ${def[0]==='direct'?'прямые':'косвенные'} · ${esc(def[1])}</td>${row.map((n,m)=>`<td><input class="driver-input" type="number" step="any" data-manual="${kind}:${k}" data-month="${m}" value="${Number((n/state.unit).toFixed(2))}"></td>`).join('')}</tr>`);}
