async function loadCurrentContractorFile(){if(!requireEdit())return;const current=contractor(),url=$('contractorFileUrl').value.trim();if(!url){notify('Укажите прямую ссылку на Excel-файл подрядчика.');return;}if(pendingContractors.has(current.id)&&!confirm('Заменить несохранённые изменения подрядчика данными из файла по ссылке?'))return;try{safeURL(url);const loaded=await contractorFromUrl({id:current.id,name:current.name,fileUrl:url}),index=state.contractors.findIndex(x=>x.id===current.id),urlChanged=current.fileUrl!==url;state.contractors[index]=loaded;state.currentContract='';state.currentVersion='';pendingContractors.delete(current.id);contractorDirty=pendingContractors.size>0;dirty=contractorDirty||configDirty;normalize();persist(urlChanged,'config');render();notify('Файл подрядчика загружен по ссылке. Браузерное хранилище не использовалось.');}catch(e){notify('Не удалось загрузить файл подрядчика: '+e.message);}}
function safeURL(path){const url=new URL(path,location.href);if(!['http:','https:','file:'].includes(url.protocol))throw Error('Допустимы ссылки HTTP(S) или относительные пути к файлам.');return url;}
