$('reloadWorkSources').onclick=()=>loadWorkSources(true);
$('kqEstimateTable').onchange=e=>{const input=e.target.closest('[data-kq-material-kind]');if(!input||!requireEdit())return;const v=version(),code=input.dataset.kqMaterialKind;if(!v?.kqEstimate?.some(row=>row.code===code)){notify('Работа KQ-2 больше не присутствует в загруженной оценке.');renderKqEstimate();return;}try{const updated=DataAdapter.setMaterialKind(v.materialKinds,code,input.value);if(JSON.stringify(updated)===JSON.stringify(v.materialKinds))return;v.materialKinds=updated;persist(true);renderKqEstimate();notify('Вид материала для '+code+' сохранён в выбранной версии. Для передачи изменений выгрузите файл подрядчика.');}catch(err){renderKqEstimate();notify(err.message);}};
for(const target of [$('portfolioSelection'),$('portfolioDetailSelection')])target.onchange=e=>{const el=e.target,include=el.dataset.portfolioInclude,choice=el.dataset.portfolioVersion,c=contractor(),id=include||choice,d=c.contracts.find(x=>x.id===id);if(!d)return;c.portfolio=c.portfolio||{versionIds:{},excluded:[]};c.portfolio.versionIds=c.portfolio.versionIds||{};c.portfolio.excluded=c.portfolio.excluded||[];if(include){c.portfolio.excluded=el.checked?c.portfolio.excluded.filter(x=>x!==id):[...new Set([...c.portfolio.excluded,id])];}else if(choice){if(!d.versions.some(v=>v.id===el.value)){notify('Версия договора не найдена.');renderPortfolio();return;}c.portfolio.versionIds[id]=el.value;}else return;persist(true);renderPortfolio();setupTableScrollRail();notify('Состав свода сохранён в файле подрядчика для следующей выгрузки.');};
$('addContractButton').onclick=()=>{if(!requireEdit())return;$('newContractor').innerHTML=state.contractors.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join('');$('newContractor').value=state.currentContractor;$('contractModal').classList.add('show');$('newContractNumber').focus();};
$('addContractorButton').textContent='Добавить';
const renameContractorButton=document.createElement('button');renameContractorButton.className='btn';renameContractorButton.id='renameContractorButton';renameContractorButton.textContent='Изменить';$('addContractorButton').after(renameContractorButton);
$('addContractorButton').onclick=()=>{if(!requireEdit())return;if(state.contractors.length>=100){notify('Можно создать не более 100 подрядчиков.');return;}const name=prompt('Наименование нового подрядчика:','Новый подрядчик');if(name===null)return;const clean=name.trim();if(!clean){notify('Укажите наименование подрядчика.');return;}if(state.contractors.some(x=>x.name.toLocaleLowerCase('ru-RU')===clean.toLocaleLowerCase('ru-RU'))){notify('Подрядчик с таким наименованием уже существует.');return;}const id=uid('c'),c={id,name:clean,sourceMapping:contractorMapping(id),contracts:[]};state.contractors.push(c);state.currentContractor=c.id;state.currentContract='';state.currentVersion='';persist(true,'both');render();notify('Подрядчик добавлен. При завершении редактирования будут скачаны его книга и актуальный config.json.');};
$('renameContractorButton').onclick=()=>{if(!requireEdit())return;const c=contractor();if(!c)return;const name=prompt('Новое наименование подрядчика:',c.name);if(name===null)return;const clean=name.trim();if(!clean){notify('Укажите наименование подрядчика.');return;}if(state.contractors.some(x=>x.id!==c.id&&x.name.toLocaleLowerCase('ru-RU')===clean.toLocaleLowerCase('ru-RU'))){notify('Подрядчик с таким наименованием уже существует.');return;}c.name=clean;persist(true,'both');render();notify('Наименование подрядчика изменено. При завершении редактирования будут скачаны его книга и актуальный config.json.');};
$('deleteContractorButton').onclick=()=>{if(!requireEdit())return;const c=contractor();if(!c)return;if(state.contractors.length===1){notify('Нельзя удалить единственного подрядчика.');return;}if(!confirm(`Удалить подрядчика «${c.name}» и все его договоры, версии и настройки?`))return;state.contractors=state.contractors.filter(x=>x.id!==c.id);pendingContractors.delete(c.id);contractorDirty=pendingContractors.size>0;state.currentContractor=state.contractors[0].id;state.currentContract='';state.currentVersion='';persist(true,'config');render();notify('Подрядчик удалён. При завершении редактирования будет скачан актуальный config.json.');};
$('contractForm').onsubmit=e=>{e.preventDefault();if(!requireEdit())return;const c=state.contractors.find(x=>x.id===$('newContractor').value),number=$('newContractNumber').value.trim(),name=$('newContractName').value.trim();if(!number||!name)return;if(c.contracts.some(x=>x.number===number)){notify('У подрядчика уже есть договор с таким номером.');return;}const d=makeContract(uid('d'),number,name);c.contracts.push(d);state.currentContractor=c.id;state.currentContract=d.id;state.currentVersion=d.versions[0].id;normalize();$('contractModal').classList.remove('show');$('contractForm').reset();persist(true);render();};
$('sourceList').onclick=e=>{const b=e.target.closest('[data-source]');if(b)openSource(b.dataset.source);};
$('sourcePreviewButton').onclick=previewFields;$('sourceSaveButton').onclick=saveSource;
$('sourceFile').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{sourceDraft=collectSource();await acceptSource(await file.arrayBuffer(),file.name);}catch(err){$('sourcePreview').textContent='Ошибка чтения: '+err.message;}finally{e.target.value='';pendingSource=null;}};
for(const el of document.querySelectorAll('[data-close]'))el.onclick=()=>$(el.dataset.close).classList.remove('show');
for(const el of document.querySelectorAll('.modalback'))el.addEventListener('click',e=>{if(e.target===el)el.classList.remove('show');});
window.addEventListener('keydown',e=>{if(e.key==='Escape')document.querySelectorAll('.modalback.show').forEach(el=>el.classList.remove('show'));});
window.addEventListener('beforeunload',e=>{if(dirty&&editMode){e.preventDefault();e.returnValue='';}});
init();
